{
 "cases": [
  {
   "name": "缺少必填字段 messages",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "缺少必填字段 model",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "temperature 超过上限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "top_p 超过上限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "top_p": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "max_tokens 超过上限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "max_tokens": 4097
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "n 超过上限",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "n": 2
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "messages 中 role 为非法值",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "invalid",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  }
 ]}
